const payload = $input.item.json.body || $input.item.json;

// Active Exception Portfolio Summary
const activeCases = [
  {
    case_id: 'EXC-4772245A',
    shipment_id: 'SHP-OCEAN-1001',
    container_no: 'MSCU1234567',
    customer: 'Apex Global Retail Corp',
    severity: 'P1_CRITICAL',
    rule_id: 'RULE_02_CUSTOMS_HOLD',
    title: 'Critical Customs Examination Hold',
    days_late: 2.25,
    revenue_at_risk: 255000.0,
    contract_penalty: 1687.50,
    stockout_probability: '90%',
    top_recommendation: 'Dedicated Team Drayage Hotshot Truck (Saves 36 hrs, Cost $1,250)',
    approval_tier: 'TIER_2_SUPERVISOR',
    status: 'OPEN'
  },
  {
    case_id: 'EXC-8819201B',
    shipment_id: 'SHP-TRUCK-2002',
    container_no: 'KNIG-53-902',
    customer: 'Titan Automotive Assembly',
    severity: 'P2_HIGH',
    rule_id: 'RULE_03_VISIBILITY_GAP',
    title: 'Tracking Visibility Gap (Road FTL > 4h)',
    days_late: 0.0,
    revenue_at_risk: 120000.0,
    contract_penalty: 0.0,
    stockout_probability: '20%',
    top_recommendation: 'Trigger Automated Carrier EDI / Dispatch Poll',
    approval_tier: 'TIER_1_AUTO',
    status: 'INVESTIGATING'
  }
];

const totalExposure = activeCases.reduce((acc, c) => acc + c.revenue_at_risk, 0);
const totalPenalties = activeCases.reduce((acc, c) => acc + c.contract_penalty, 0);

return {
  json: {
    status: 'CONTROL_TOWER_DESK_EVALUATED',
    report_timestamp: new Date().toISOString(),
    total_active_exceptions: activeCases.length,
    p1_critical_count: activeCases.filter(c => c.severity === 'P1_CRITICAL').length,
    p2_high_count: activeCases.filter(c => c.severity === 'P2_HIGH').length,
    financial_summary: {
      total_revenue_at_risk: '$' + totalExposure.toLocaleString(),
      accumulated_contract_penalties: '$' + totalPenalties.toLocaleString()
    },
    active_cases: activeCases
  }
};

const data = $input.item.json;
const briefing = `🚨 *DAILY CONTROL TOWER EXCEPTION BRIEFING* 🚨\n\n` +
`• Total Active Exceptions : ${data.total_active_exceptions} (Critical P1: ${data.p1_critical_count}, High P2: ${data.p2_high_count})\n` +
`• Total Value at Risk    : ${data.financial_summary.total_revenue_at_risk}\n` +
`• Contract Penalties     : ${data.financial_summary.accumulated_contract_penalties}\n\n` +
`*Top Priority Incident:*\n` +
`  - Case: ${data.active_cases[0].case_id} (${data.active_cases[0].title})\n` +
`  - Customer: ${data.active_cases[0].customer} [${data.active_cases[0].severity}]\n` +
`  - Proposed Action: ${data.active_cases[0].top_recommendation}\n` +
`  - Governance: Requires ${data.active_cases[0].approval_tier} sign-off.`;

return {
  json: {
    status: 'BRIEFING_BROADCASTED',
    channel: '#control-tower-executive',
    slack_formatted_message: briefing,
    raw_summary: data
  }
};
